INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "钟传", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：钟传。", "biography": null, "status": "draft", "id": "8a85c94c-50e4-553d-bd94-75699a83c264"}, {"name": "杜洪", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的杜洪，在此段中为逐刺史并取代者。", "biography": null, "status": "draft", "id": "9091e17c-39e3-5f00-8d0f-e054c1147b48"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱友恭", "aliases": ["李彦威", "硃友恭"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：朱友恭。", "biography": null, "status": "draft", "id": "3cf1cc65-22b1-57da-951d-b72c2d25f10f"}, {"name": "董昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：董昌。", "biography": null, "status": "draft", "id": "873d5b10-b461-5308-baa9-da26022436b4"}, {"name": "袁邠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：袁邠。", "biography": null, "status": "draft", "id": "1e9b8e5c-29c8-5223-b927-08168dfe8b65"}, {"name": "顾全武", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：顾全武。", "biography": null, "status": "draft", "id": "82b73ae4-434c-5208-8a2d-89b0830434c2"}, {"name": "许再思", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：许再思。", "biography": null, "status": "draft", "id": "d8f0fe35-6617-53d5-911b-2680c6a59c66"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "张佶", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张佶。", "biography": null, "status": "draft", "id": "3e2c7882-9436-5f5d-8d37-e452a1db7890"}]'::jsonb)
