INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "淮南镇海战皇天荡，镇海不利", "start_year": 896, "end_year": 896, "time_original": "896年四月条；确日未载", "dynasty": "唐", "description": "淮南兵与镇海兵在皇天荡交战，镇海军不利。", "phases": [], "location_name": "皇天荡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "54cd0d5f-e31b-53c7-8cf6-ec01b55ed355"}, {"title": "杨行密继而围苏州", "start_year": 896, "end_year": 896, "time_original": "896年四月皇天荡战后条；确日未載", "dynasty": "唐", "description": "杨行密继而围苏州。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "69cedc0c-9aa4-57c7-806b-a697612a1713"}, {"title": "钱镠钟传杜洪向朱温求援", "start_year": 896, "end_year": 896, "time_original": "896年四月条；确日未载", "dynasty": "唐", "description": "钱镠、钟传、杜洪惧杨行密强大，均向朱温请求援助。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b2328a84-a653-56b6-9f9d-cfde58ce6624"}, {"title": "朱温遣朱友恭万人渡淮，许便宜行事", "start_year": 896, "end_year": 896, "time_original": "896年四月求援以后；确日未载", "dynasty": "唐", "description": "朱温派许州刺史朱友恭率一万兵渡淮，准其自行处置军务。", "phases": [], "location_name": "淮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ed7c399a-aadd-5b46-b62a-04a3ac1c2294"}, {"title": "董昌杀报钱军强者，赏报疲乏者", "start_year": null, "end_year": null, "time_original": "卷260乾宁三年条背景；多次侦报起讫未载", "dynasty": "唐", "description": "董昌派人窥察钱镠军。有人报告军势强盛便被怒斩，报告兵疲食尽则获奖。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "292da988-1e20-582f-929f-2347c0c934ed"}, {"title": "袁邠以馀姚降钱镠", "start_year": 896, "end_year": 896, "time_original": "896年四月戊寅", "dynasty": "唐", "description": "袁邠以馀姚向钱镠投降。", "phases": [], "location_name": "馀姚", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10577d64-d8b6-569f-9d37-e39b17201ad6"}, {"title": "顾全武许再思进抵越州城下", "start_year": 896, "end_year": 896, "time_original": "896年四月袁邠降后条；确日未另载", "dynasty": "唐", "description": "顾全武、许再思进军到越州城下。", "phases": [], "location_name": "越州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d0f8c52d-22be-54aa-8225-4484afa94c94"}, {"title": "董昌五月出战败，顾全武等围越州", "start_year": 896, "end_year": 896, "time_original": "896年五月；确日未載", "dynasty": "唐", "description": "董昌出战失败，退守城内，顾全武等包围他。", "phases": [], "location_name": "越州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e39b8020-9be0-5940-be04-4139cca5d562"}, {"title": "董昌惧，去帝号复称节度使", "start_year": 896, "end_year": 896, "time_original": "896年五月败战被围以后；确日未另载", "dynasty": "唐", "description": "董昌开始惧怕，取消帝号，又称节度使。", "phases": [], "location_name": "越州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8800f741-3357-5d6d-b6ba-2fd432924de9"}, {"title": "马殷抵长沙，张佶让留后并拜贺", "start_year": 896, "end_year": 896, "time_original": "896年五月条；到长沙及让位确日未载", "dynasty": "唐", "description": "马殷到长沙，张佶坐肩舆入府受其拜谒，随后让马殷升堂并让留后位，自己下堂率将吏拜贺。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "39d9989b-ae4a-52c7-b37b-23ab1bc6db85"}, {"title": "张佶复行军司马，代马殷攻邵州", "start_year": 896, "end_year": 896, "time_original": "896年五月让位后条；确日未载", "dynasty": "唐", "description": "张佶又任行军司马，替马殷率军攻邵州。", "phases": [], "location_name": "邵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b0c507dc-39b3-57fb-bb96-2e39710a1709"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

